head.script:
scwin.gEmpNo;
scwin.gAcptNo; // 접수번호
scwin.gLdMktTpCd; // 상장공시시장구분
scwin.strSch; // 경과사유
scwin.gDelayTm;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name setParamData
 * @description 부모창의 데이타 셋팅하기
 * @returns {void}
 * @hidden N
 */
scwin.setParamData = function() {
    scwin.gEmpNo = js_emp_no; // 세션정보

    scwin.gAcptNo = $c.frame.path("../").scwin.gAcptNo;
    scwin.strSch = $c.frame.path("../").gProgRsnCd;
    scwin.gDelayTm = $c.frame.path("../").scwin.gDelayTm;

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !X-- > async function() {
    const sbmOptions = {
        id : "sbm_dts_DelayInfo",
        action : "/DisclosureStatus.do",
        ref : "",
        target : "dts_DelayInfo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name modify
 * @description 경과사유 변경처리하기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modify = async function() {
    const vProgRsn = cmb_ProgRsn.getValue();
    if (vProgRsn.length < 1) {
        await $c.win.alert("처리지연(경과)유형을 선택하시오.");
        cmb_ProgRsn.focus();
        return;
    }
    if ($c.stf.checkMaxLength(txb_ProgRsn, 200, '경과사유') === false) {
        return;
    }
    dts_ProgRsnInfo.insertRow();
    dts_ProgRsnInfo.setCellData(1, "ACPT_NO", scwin.gAcptNo);
    dts_ProgRsnInfo.setCellData(1, "PROG_RSN_CD", vProgRsn);
    dts_ProgRsnInfo.setCellData(1, "DELAY_TM", scwin.gDelayTm);
    dts_ProgRsnInfo.setCellData(1, "PROG_RSN", txb_ProgRsn.getValue());
    dts_ProgRsnInfo.setCellData(1, "EMP_NO", scwin.gEmpNo);
    const vAnswer = confirm('공시경과사유를 변경하시겠습니까?');
    if (vAnswer === true) {
        trs_ProgRsn.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_ProgRsn",
            action : "/DisclosureStatus.do",
            ref : "dts_ProgRsnInfo",
            target : "trs_ProgRsn=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    await scwin.modify();
};

/**
 * @method
 * @name trs_ProgRsn_OnSuccess
 * @description Prog Rsn On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_ProgRsn_OnSuccess = async function() {
    await $c.win.alert("성공적으로 저장되었습니다.");
    await $c.win.closePopup();

    // 부모창의   reload 처리해야함
    $c.frame.path("../").fn_Search();
};

/**
 * @method
 * @name trs_ProgRsn_OnFail
 * @description Prog Rsn On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_ProgRsn_OnFail = async function() {
    await $c.win.alert('trs_ProgRsn.OnFail() :' + trs_ProgRsn.ErrorMsg);
};

/**
 * @method
 * @name dts_DelayInfo_OnLoadError
 * @description dts_DelayInfo 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DelayInfo_OnLoadError = async function() {
    await $c.win.alert(dts_DelayInfo);
};

/**
 * @method
 * @name dts_ProgRsn_OnLoadCompleted
 * @description 초기1회 초기값으로 설정된 사유분류를 검색한다.
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ProgRsn_OnLoadCompleted = function(rowcount) {
    // 초기1회 초기값으로 설정된 사유분류를 검색한다.
    if (scwin.strSch !== "") {
        for (let i = 1; i <= dts_ProgRsn.getRowCount(); i++) {
            if (scwin.strSch === dts_ProgRsn.getCellData(i, 1)) {
                dts_ProgRsn.setRowPosition(i, 0);
                break;
            }
        }
        scwin.strSch = "";
    }
};

/**
 * @method
 * @name bnt_Close_onclick
 * @description 「취소」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.bnt_Close_onclick = async function() {
    await $c.win.closePopup();
};

/**
 * @method
 * @name gform_onload
 * @description 패널라운드 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    // 패널라운드 처리
    $c.libRoundPanel.PanelToGroupBox(pnl_1);
    scwin.setParamData();

    // 가우스헤더 셋팅
    const sbmOptions = {
        id : "sbm_dts_ProgRsnInfo",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_ProgRsnInfo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 경과사유 리스트  셋팅
    const sbmOptions2 = {
        id : "sbm_dts_ProgRsn",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_ProgRsn=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 경과사유 읽어오기
    fn_DelayRead();
};
